arguments.command:
curl -s "https://api.box.com/2.0/folders/100/items?limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d['entries']:
    if e['type']=='file' and e['name'].lower().endswith('.pdf'):
        ob=e.get('owned_by') or {}
        mby=e.get('modified_by') or {}
        print(e['id'], repr(e['name']), 'owner:', ob.get('name'), 'modified_by:', mby.get('name'), 'modified_at:', e.get('modified_at'))
"

